cat > /workspace/checks/authorization.cjs <<'EOF'
const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const snapshot = (repo) => JSON.parse(JSON.stringify({ docs: repo.documents, audit: repo.audit }));
const expectFailure = (repo, fn, message) => {
  const before = snapshot(repo);
  assert.throws(fn, (error) => error instanceof Error && error.message === message);
  assert.deepEqual(snapshot(repo), before, 'failure must leave documents and audit unchanged');
};

{
  // admin archives any visible document; repeat is a no-op and audit has exactly one entry
  const repo = new DocumentRepository([
    { id: 'one', tenant: 'a', owner: 'other', deleted: false, archived: false },
    { id: 'two', tenant: 'a', owner: 'u', deleted: false, archived: true },
  ]);
  const service = new DocumentService(repo);
  const admin = { tenant: 'a', user: 'admin-user', role: 'admin' };
  service.archive(admin, 'one');
  assert.equal(repo.documents[0].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'admin-user', document: 'one' }]);
  service.archive(admin, 'one');
  assert.deepEqual(repo.audit, [{ actor: 'admin-user', document: 'one' }]);
  service.archive(admin, 'two');
  assert.deepEqual(repo.audit, [{ actor: 'admin-user', document: 'one' }]);
}

{
  // missing, deleted and foreign-tenant are invisible to everyone, including admin
  const repo = new DocumentRepository([
    { id: 'gone', tenant: 'a', owner: 'x', deleted: true, archived: false },
    { id: 'elsewhere', tenant: 'b', owner: 'admin-user', deleted: false, archived: false },
  ]);
  const service = new DocumentService(repo);
  for (const role of ['admin', 'editor', 'viewer']) {
    const actor = { tenant: 'a', user: 'admin-user', role };
    expectFailure(repo, () => service.archive(actor, 'missing'), 'not found');
    expectFailure(repo, () => service.archive(actor, 'gone'), 'not found');
    expectFailure(repo, () => service.archive(actor, 'elsewhere'), 'not found');
  }
}

{
  // editor may archive only documents they own
  const repo = new DocumentRepository([
    { id: 'mine', tenant: 'a', owner: 'ed', deleted: false, archived: false },
    { id: 'theirs', tenant: 'a', owner: 'other', deleted: false, archived: false },
    { id: 'archived-mine', tenant: 'a', owner: 'ed', deleted: false, archived: true },
    { id: 'archived-theirs', tenant: 'a', owner: 'other', deleted: false, archived: true },
  ]);
  const service = new DocumentService(repo);
  const editor = { tenant: 'a', user: 'ed', role: 'editor' };
  service.archive(editor, 'mine');
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'mine' }]);
  service.archive(editor, 'archived-mine');
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'mine' }]);
  expectFailure(repo, () => service.archive(editor, 'theirs'), 'forbidden');
  expectFailure(repo, () => service.archive(editor, 'archived-theirs'), 'forbidden');
}

{
  // viewer never may archive, even own or already archived visible documents
  const repo = new DocumentRepository([
    { id: 'visible', tenant: 'a', owner: 'v', deleted: false, archived: false },
    { id: 'archived', tenant: 'a', owner: 'v', deleted: false, archived: true },
  ]);
  const service = new DocumentService(repo);
  const viewer = { tenant: 'a', user: 'v', role: 'viewer' };
  expectFailure(repo, () => service.archive(viewer, 'visible'), 'forbidden');
  expectFailure(repo, () => service.archive(viewer, 'archived'), 'forbidden');
}

console.log('authorization checks passed');
EOF
